entries[160648] = { ["name"] = "Frenetisches Korpuskel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, Euch für 45 Sek. 'Schäumende Wut' zu gewähren. Beim Erreichen von 4 Stapeln von 'Schäumende Wut' verursacht Euer nächster Angriff zusätzlich 61 körperlichen Schaden.\nVerkaufspreis:" }
entries[160649] = { ["name"] = "Immunisierendes Extrakt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nBenutzen: Injiziert einem verbündeten Ziel für 30 Sek. 5 Stapel von 'Mutierende Antikörper'. Eure auf diesen Verbündeten gewirkten direkten Heilungen zehren einen Stapel von 'Mutierende Antikörper' auf und stellen zusätzlich 56 Gesundheit wieder her. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[160650] = { ["name"] = "Scheibe der systematischen Regression", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nAnlegen: Eure Angriffe haben eine Chance, einen Leerensektor zu erzeugen. Er verursacht sofort 72 Schattenschaden, der unter allen Zielen in einem kegelförmigen Bereich vor Euch aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht.\nVerkaufspreis:" }
entries[160651] = { ["name"] = "Blutformer der Wachsamen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, eine Kugel geladenen Blutes auf Euer Ziel abzufeuern. Sie verursacht 91 Schattenschaden, der unter allen Gegnern in der Nähe aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht.\nVerkaufspreis:" }
entries[160652] = { ["name"] = "Konstruktüberlader", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, Euer Tempo 10 Sek. lang um 3 zu erhöhen. Bis zu 8-mal stapelbar.\nVerkaufspreis:" }
entries[160653] = { ["name"] = "Xalzaix' verschleiertes Auge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nAnlegen: Wenn Eure Gesundheit unter 40% fällt, erhaltet Ihr einen Schild, der 50% des eintreffenden Schadens absorbiert [bis zu einem Maximum von ( 750 * (1 + Vielseitigkeit)) Schaden]. Hält 20 Sek. lang an. Dieser Effekt kann nur ein Mal alle 2 Min. auftreten.\nVerkaufspreis:" }
entries[160654] = { ["name"] = "G'huuns bezwungenes Tentakel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 9 Vielseitigkeit\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, eines von G'huuns bezwungenen Tentakeln zu beschwören, das Euch 20 Sek. lang dient. (20s Abklingzeit)\nVerkaufspreis:" }
entries[160655] = { ["name"] = "Spritze der blutübertragenen Schwäche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nAnlegen: Eure Angriffe haben eine Chance, eine zehrende Infektion hervorzurufen, die im Verlauf von 12 Sek. ( 5 * 12 / 2) Schattenschaden verursacht. Angriffe auf ein Ziel, das an der zehrenden Infektion leidet, erhöhen Euren kritischen Trefferwert für 6 Sek. um 5 . Dieser Effekt ist bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[160656] = { ["name"] = "Zuckendes Tentakel von Xalzaix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 9.\nAnlegen: Eure Zauber haben eine Chance, Euch für 30 Sek. mit der verbleibenden Macht von Xalzaix zu stärken. Beim Erreichen von 5 Stapeln wird die Macht entfesselt, wodurch Eure Intelligenz 12 Sek. lang um 25 erhöht wird.\nVerkaufspreis:" }
