entries[160661] = { ["name"] = "Rezept: Feuerammonitenöl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Feuerammonitenöl.\nErschafft 4 Stück Feuerammonitenöl. Die tatsächliche Anzahl kann basierend auf der Fertigkeitsstufe variieren.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nFeuerammonitenöl\nBenutzen: Heilt Krankheiten und verringert die Wirkungsdauer nachfolgender Krankheiten 2 Min. lang um 50%. Funktioniert nur in Draenor. Kann nicht in Instanzen verwendet werden. Funktioniert nicht über Stufe 50. (2 Min Abklingzeit)\n\"Brennt Infektionen aus, ohne dem Wirt zu schaden.\"\nBenötigt Feuerammonittentakel (10)" }
entries[160662] = { ["name"] = "Rezept: Schwarzwassergegengift", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Schwarzwassergegengifts.\nErschafft 4 Stück Schwarzwassergegengift. Die tatsächliche Anzahl kann basierend auf der Fertigkeitsstufe variieren.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nSchwarzwassergegengift\nBenutzen: Heilt Gifte bis Stufe 49 und verringert die Wirkungsdauer nachfolgender Gifte 2 Min. lang um 50%. Funktioniert nur in Draenor. Kann nicht in Instanzen verwendet werden. (2 Min Abklingzeit)\nBenötigt Fleisch einer Schwarzwasserpeitschflosse (10)" }
entries[160663] = { ["name"] = "Rezept: Heiltonikum", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Heiltonikums.\nErschafft 4 Stück Heiltonikum. Die tatsächliche Anzahl kann basierend auf der Fertigkeitsstufe variieren.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nHeiltonikum\nBenutzen: Stellt 3400 Gesundheit wieder her. (5 Min Abklingzeit)\n\"Richtig vorbereitet kann das Gift des Seeskorpions Gesundheit wiederherstellen.\"\nVerkaufspreis:\nBenötigt Seeskorpionsegment (10)" }
entries[160664] = { ["name"] = "Rezept: Silbrige Salbe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung einer silbrigen Salbe.\nStellt eine silbrige Salbe her.\nBenötigt Alchemie der Verheerten Inseln\n(30)\nVerkaufspreis:\nSilbrige Salbe\nBenutzen: Heilt im Verlauf von 8 Sek. 5400 Gesundheit.\nVerkaufspreis:\nBenötigt Silbermakrele (5)" }
