entries[161664] = { ["name"] = "Zügel der spektralen Pterrorschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine spektrale Pterrorschwinge beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Zandalariimperium\n- Ehrfürchtig\nErforderlicher Erfolg: Pfadfinder von Battle for Azeroth, Teil zwei.\n\n\"Von diesen rachsüchtigen Geistern finden sich reichlich im Geisterreich um Dazar'alor.\"\nVerkäufer:\nNatal'hakata\nZone:\nZuldazar\nFraktion:\nZandalariimperium - Ehrfürchtig\nKosten:\n90." }
entries[161665] = { ["name"] = "Zügel des Kobaltpterrordax", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Kobaltpterrordax beschwört.\nBeschwört Euren gepanzerten Kobaltpterrordax oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Zandalariimperium\n- Ehrfürchtig\n\n\"Diese Pterrordaxe fliegen hoch über den Küsten von Zandalar und halten Ausschau nach feindlichen Flotten.\"\nVerkäufer:\nNatal'hakata\nZone:\nZuldazar\nFraktion:\nZandalariimperium - Ehrfürchtig\nKosten:\n10." }
entries[161666] = { ["name"] = "Zügel des gefangenen Morastpirschers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen gefangenen Morastpirscher beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Talanjis Expedition\n- Ehrfürchtig\nErforderlicher Erfolg: Pfadfinder von Battle for Azeroth, Teil zwei.\n\n\"Eine in Sümpfen hausende Unterart von Pterrordaxen, die sich von jungen Blutschmausern ernährt.\"\nVerkäufer:\nVersorgerin Lija\nZone:\nNazmir\nFraktion:\nTalanjis Expedition - Ehrfürchtig\nKosten:\n90." }
entries[161667] = { ["name"] = "Zügel des Dünenreißers der Voldunai", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Dünenreißer der Voldunai beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Voldunai\n- Ehrfürchtig\nErforderlicher Erfolg: Pfadfinder von Battle for Azeroth, Teil zwei.\n\n\"Diese fliegenden Wesen mit leuchtenden Farben werden wegen ihrer misstrauischen Natur nur selten wild gefangen.\"\nVerkäufer:\nHorterin Jena\nZone:\nVol'dun\nFraktion:\nVoldunai - Ehrfürchtig\nKosten:\n90." }
